import { useId, useState } from 'react';
import { JxAlert, JxButton, JxInput, JxSelect, JxSwitch } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

export default function TeamInviteForm() {
  const formId = useId();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const showError = touched && !isValid;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <div
      style={{
        display: 'grid',
        gap: 'var(--jx-space-4, 1rem)',
        maxWidth: 'var(--jx-size-form, 28rem)',
      }}
    >
      {invitedEmail !== null && (
        <JxAlert
          open
          onOpenChange={(open: boolean) => {
            if (!open) setInvitedEmail(null);
          }}
          variant="success"
          dismissible
          title="Приглашение отправлено"
        >
          {invitedEmail} получит доступ с ролью «
          {ROLES.find((item) => item.value === role)?.label}».
        </JxAlert>
      )}

      <form
        id={formId}
        onSubmit={handleSubmit}
        noValidate
        style={{ display: 'grid', gap: 'var(--jx-space-4, 1rem)' }}
      >
        <JxInput
          type="email"
          name="email"
          label="Почта"
          placeholder="name@company.com"
          autoComplete="email"
          value={email}
          onValueChange={setEmail}
          onBlur={() => setTouched(true)}
          hint="Пригласим по адресу рабочей почты — личные ящики тоже подойдут."
          invalid={showError}
          error={showError ? 'Введите адрес в формате name@company.com' : undefined}
        />

        <JxSelect
          name="role"
          label="Роль"
          value={role}
          onValueChange={setRole}
          options={ROLES}
        />

        <JxSwitch
          name="notify"
          label="Отправить уведомление"
          hint="Письмо со ссылкой уйдёт сразу после приглашения."
          value={notify}
          onValueChange={setNotify}
        />

        <JxButton type="submit" variant="primary" disabled={!isValid}>
          Пригласить
        </JxButton>
      </form>
    </div>
  );
}

